def copiar_niveles_stock(apps, schema_editor):
    Producto = apps.get_model("catalogo", "Producto")
    for producto in Producto.objects.all().iterator():
        minimo = producto.punto_reorden or 0
        producto.stock_minimo = minimo
        producto.stock_ideal = max(minimo * 4, 20)
        producto.save(update_fields=["stock_minimo", "stock_ideal"])


